<h1>Data Pengurus</h1><section class="card"><h2>Tambah Pengurus</h2><form method="post" action="<?= BASE_URL ?>/index.php?url=pengurus/store" class="form-grid">
<label>Nama Pengurus<input name="nama_pengurus" required></label><label>NIM<input name="nim" required></label><label>Jabatan<input name="jabatan" required></label>
